\begin{aligned}
\mathrm{IsFiltering}(\mathcal I)\leftrightarrow{}&\mathrm{IsSmallCategory}(\mathcal I)\land\mathrm{Ob}(\mathcal I)\ne\varnothing\\
&\land\forall i,j\in\mathrm{Ob}(\mathcal I)\ \exists k\in\mathrm{Ob}(\mathcal I)\ (\mathrm{Hom}_{\mathcal I}(k,i)\ne\varnothing\land\mathrm{Hom}_{\mathcal I}(k,j)\ne\varnothing)\\
&\land\forall i,j\in\mathrm{Ob}(\mathcal I)\ \forall u,v\in\mathrm{Hom}_{\mathcal I}(i,j)\ \exists k\in\mathrm{Ob}(\mathcal I)\ \exists w\in\mathrm{Hom}_{\mathcal I}(k,i)\ (u\circ w=v\circ w).
\end{aligned}
